#!/usr/bin/env python3
"""Build distinctly labeled derived emptiness, never fabricated direct runs."""
import argparse,hashlib,json,pathlib
p=argparse.ArgumentParser();p.add_argument('--recipe',required=True);p.add_argument('--raw',action='append',required=True);p.add_argument('--out',required=True);a=p.parse_args();recipe_path=pathlib.Path(a.recipe);recipe=json.loads(recipe_path.read_text());assert recipe['phase']=='tune_larger_reference_tier_not_primary_replacement';jobs={j['query_id']:j for j in recipe['jobs']};certs=[]
for file in a.raw:
 path=pathlib.Path(file);raw=path.read_bytes();xs=[json.loads(s) for s in raw.decode().splitlines()];meta=xs[0];assert meta['kind']=='metadata';assert meta['build_source_sha256']==recipe['corrected_source_sha256'],'corrected source binding mismatch';assert meta['max_labels']==4000000 and meta['max_transitions']==300000000
 for x in xs[1:]:
  if x.get('kind')!='scalar_result':continue
  q=x['query'];j=jobs[q['id']];assert hashlib.sha256(json.dumps(q,sort_keys=True,separators=(',',':')).encode()).hexdigest()==j['unchanged_query_sha256'];assert meta['workload_sha256']==j['queries_sha256'];source_dataset_sha=hashlib.sha256(pathlib.Path(j['dataset']).read_bytes()).hexdigest();assert meta['dataset_sha256']==source_dataset_sha
  r=x['result']
  if not r['complete'] or r['found'] or x.get('error') or x['oracle_elapsed_ns']>60000000000:continue
  certs.append({'kind':'derived_empty_reference','query':q,'dataset_sha256':source_dataset_sha,'derivation':'An independent resource-label-setting search exhausted its entire feasible-label queue without a destination on this unchanged dataset/query contract. Feasibility is independent of scalar weights. Therefore every nonnegative-weight scalar problem on the same feasible universe is empty. This is a logical derivation, not additional executions.','source_direct_file':str(path),'source_direct_file_sha256':hashlib.sha256(raw).hexdigest(),'source_direct_weight':x['weight'],'source_direct_weight_index':x['weight_index'],'source_direct_build_sha256':meta['build_source_sha256'],'source_direct_slot_elapsed_ns':x['oracle_elapsed_ns'],'applies_to_nonnegative_weights':True,'original_primary_raw_outcomes_remain':'inconclusive for the original9 offered slots; not overwritten or counted as direct completed runs','derived_original_weight_slots':9})
report={'raw_direct_executions':sum(len(pathlib.Path(f).read_text().splitlines())-1 for f in a.raw),'derived_query_certificates':len(certs),'derived_original_weight_slots':sum(c['derived_original_weight_slots'] for c in certs),'recipe_sha256':hashlib.sha256(recipe_path.read_bytes()).hexdigest(),'certificates':certs};out=pathlib.Path(a.out);out.open('x').write(json.dumps(report,sort_keys=True,indent=2)+'\n');print(json.dumps({'direct_executions':report['raw_direct_executions'],'derived_queries':len(certs),'derived_original_slots':report['derived_original_weight_slots']}))
